INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('the-master-and-the-disciple', 'Islamic', 'The Master and the Disciple', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('the-master-and-the-disciple', 'كتاب العالم والغلام', 'ar', 'esoteric', '<p>This is a work of religious instruction cast as a story: a chain of encounters between a learned man and a young seeker, built almost entirely from their talk. Its Arabic title, <em>Kitab al-Alim wa-l-Ghulam</em> — the book of the Alim and the Ghulam, the Master and the Disciple — names its two roles directly, and the dialogue between them drives the whole. Doctrine is not laid out as a treatise; it is drawn out question by question, one figure pressing and the other answering, in the manner of a Socratic exchange.</p>', NULL, 'the-master-and-the-disciple/cover.png', 'the-master-and-the-disciple/book.pdf', '2026-08-29T20:17:47Z', '46129cd6f0dc8a11ac4bdab0739b9368abc93429');
